package com.nanless.paperdigest.zotero.webdav

import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.io.RandomAccessFile
import java.nio.file.Files
import java.security.MessageDigest
import java.util.UUID
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

class ZoteroDavCodecTest {
    private fun target(base:String="https://dav.example.org/dav/",type:String="users",user:String="123",username:String="synthetic-account")=ZoteroDavTarget.native(type,user,base,username,UUID.randomUUID().toString(),UUID.randomUUID().toString())
    private fun rejects(block:()->Unit){try{block()}catch(_:Exception){return};throw AssertionError("Expected refusal")}
    private fun hash(bytes:ByteArray,algorithm:String="SHA-256")=davHex(MessageDigest.getInstance(algorithm).digest(bytes))
    private fun facts(bytes:ByteArray)=JSONObject().put("bytes",bytes.size).put("sha256",hash(bytes)).put("md5",hash(bytes,"MD5")).put("mtime",1_800_000_000_000L)
    private fun fixture(body:(File,File,ZoteroDavAttachment)->Unit){val root=Files.createTempDirectory("dav-format-").toFile().canonicalFile;val file=File(root,"source").apply{writeBytes("Synthetic Unicode 内容😀 \u0000 exact original bytes".toByteArray());setLastModified(1_800_000_000_001L)};val before=file.readBytes();try{body(root,file,ZoteroDavAttachment.native("ABCD2345","BCDE3456","pdf","paper-a","b".repeat(64),"合成标题","application/pdf",file,hash(before)))}finally{assertArrayEquals(before,file.readBytes());root.deleteRecursively()}}
    @Test fun actualCanonicalBaseAppendsZoteroExactlyOnce(){assertEquals("https://dav.example.org/dav/zotero/",target("HTTPS://DAV.EXAMPLE.ORG:443/d%61v").root);assertEquals("https://dav.example.org/zotero/",target("https://dav.example.org").root);assertEquals("https://dav.example.org/a%20b/zotero/",target("https://dav.example.org/a%20b/").root)}
    @Test fun groupAndInvalidLibraryIdsReject(){for(type in listOf("groups","user","","USERS"))rejects{target(type=type)};for(id in listOf("0","-1","1.0","true","123/../456","12345678901234567"))rejects{target(user=id)}}
    @Test fun urlCredentialsAndQueryFragmentNeverAccepted(){for(s in listOf("http://dav.example.org/","https://u:p@dav.example.org/","https://dav.example.org/?x=1","https://dav.example.org/?","https://dav.example.org/#","https://dav.example.org/#x","https://dav.example.org:0/","https://dav.example.org:65536/"))rejects{target(s)}}
    @Test fun privateLiteralAndLocalHostTargetsRefuseBeforeAnything(){for(s in listOf("https://localhost/","https://a.local/","https://127.0.0.1/","https://10.0.2.2/","https://[::1]/","https://169.254.1.1/","https://a.internal/"))rejects{target(s)}}
    @Test fun rawDecodedAndDoubleDecodedTraversalOrSeparatorRefuse(){for(path in listOf("/../","/./","/%2e%2E/","/%252e%252e/","/a%2fb/","/a%5cb/","/a\\b/","//other/","/%00/","/%FF/","/%E0%A0/","/%/"))rejects{target("https://dav.example.org$path")}}
    @Test fun rootAndAccountStringsDoNotLoseInvalidUtf16(){rejects{target("https://dav.example.org/\uD800/")};rejects{target(username="bad\uD800")};for(u in listOf("", "u:p", "u\nv"))rejects{target(username=u)}}
    @Test fun alreadyAppendedDirectoryIsExplicitlyRejected(){for(path in listOf("/zotero/","/dav/zotero","/dav/%7Aotero/","/dav/Zotero/"))rejects{target("https://dav.example.org$path")}}
    @Test fun exactPropertiesPublicProtocolVector(){val md5="0123456789abcdef0123456789abcdef";val b="<properties version=\"1\"><mtime>1800000000001</mtime><hash>$md5</hash></properties>".toByteArray();assertArrayEquals(b,ZoteroDavCodec.properties(1800000000001,md5));assertEquals(1800000000001L to md5,ZoteroDavCodec.parseProperties(b))}
    @Test fun propertiesRejectEntitiesDtdUnknownGrammarAndInvalidUtf8(){val hash="a".repeat(32);for(s in listOf("<!DOCTYPE p SYSTEM 'https://evil.invalid'><properties version=\"1\"><mtime>1</mtime><hash>$hash</hash></properties>","<properties version=\"1\"><mtime>&x;</mtime><hash>$hash</hash></properties>","<properties version=\"2\"><mtime>1</mtime><hash>$hash</hash></properties>","<properties version=\"1\"><mtime>0</mtime><hash>$hash</hash></properties>","<properties version=\"1\"><mtime>1</mtime><hash>${hash.uppercase()}</hash><extra/></properties>"))rejects{ZoteroDavCodec.parseProperties(s.toByteArray())};rejects{ZoteroDavCodec.parseProperties(byteArrayOf(0xff.toByte()))};rejects{ZoteroDavCodec.parseProperties(ByteArray(4097))}}
    @Test fun singleEntryZipPreservesExactOriginalAndColdProof(){fixture{root,file,m->val codec=ZoteroDavCodec(File(root,"transfers"));val t=target();val p=codec.prepare(m,t);val plan=codec.verify(p,t);assertEquals(file.length(),plan.getJSONObject("file").getLong("bytes"));assertEquals(1_800_000_000_001L,plan.getJSONObject("file").getLong("mtime"));java.util.zip.ZipFile(File(p.journal.dir,"attachment.zip")).use{z->assertEquals(1,z.size());assertArrayEquals(file.readBytes(),z.getInputStream(z.getEntry("pdf.pdf")).readBytes())};val before=File(p.journal.dir,"attachment.zip").readBytes();val cold=ZoteroDavCodec(File(root,"transfers"));val opened=cold.reopen(p.id,t);assertEquals(p.id,opened.id);assertArrayEquals(before,File(opened.journal.dir,"attachment.zip").readBytes())}}
    @Test fun insufficientOrUnknownAvailableSpaceRefusesBeforeMaterialCopies(){for(free in listOf(0L,-1L,1L)){fixture{root,_,m->val codec=ZoteroDavCodec(File(root,"transfers")){free};rejects{codec.prepare(m,target())};assertEquals(0,File(root,"transfers").listFiles()!!.size)}}}
    @Test fun sourceChecksumChangeKeepsSourceAndCreatesNoSuccessJournal(){fixture{root,file,m->val wrong=ZoteroDavAttachment.native(m.key,m.parentKey,m.role,m.paperID,m.sourceIdentity,m.title,m.contentType,file,"f".repeat(64));rejects{ZoteroDavCodec(File(root,"transfers")).prepare(wrong,target())};assertTrue(File(root,"transfers").listFiles()!!.all{!File(it,"journal.json").exists()})}}
    @Test fun sourceSymlinkAndControlledRootSymlinkRefuse(){fixture{root,file,m->val link=File(root,"link");Files.createSymbolicLink(link.toPath(),file.toPath());rejects{ZoteroDavAttachment.native(m.key,m.parentKey,m.role,m.paperID,m.sourceIdentity,m.title,m.contentType,link,m.sourceSHA256)};val outside=File(root,"outside").apply{mkdir()};val control=File(root,"transfers");Files.createSymbolicLink(control.toPath(),outside.toPath());rejects{ZoteroDavCodec(control)};assertTrue(outside.listFiles()!!.isEmpty())}}
    @Test fun sameNamedReplacementRootCannotReopenOrWrite(){fixture{root,_,m->val control=File(root,"transfers");val codec=ZoteroDavCodec(control);val t=target();val p=codec.prepare(m,t);assertTrue(control.renameTo(File(root,"retained")));assertTrue(control.mkdir());rejects{codec.verify(p,t)};assertTrue(control.listFiles()!!.isEmpty());assertTrue(File(root,"retained/${p.id}/journal.json").isFile)}}
    @Test fun sameNamedOperationDirectoryReplacementCannotReceiveWrites(){fixture{root,_,m->val codec=ZoteroDavCodec(File(root,"transfers"));val t=target();val p=codec.prepare(m,t);val old=File(p.journal.dir.parentFile,"retained");assertTrue(p.journal.dir.renameTo(old));assertTrue(p.journal.dir.mkdir());rejects{p.journal.update{it.put("phase","forged")}};assertTrue(p.journal.dir.listFiles()!!.isEmpty());assertTrue(File(old,"journal.json").isFile)}}
    @Test fun invalidUtf8JournalNotSilentlyEquivalent(){fixture{root,_,m->val codec=ZoteroDavCodec(File(root,"transfers"));val p=codec.prepare(m,target());File(p.journal.dir,"journal.json").writeBytes(byteArrayOf(0xff.toByte()));rejects{codec.reopen(p.id,target())};assertArrayEquals(byteArrayOf(0xff.toByte()),File(p.journal.dir,"journal.json").readBytes())}}
    @Test fun operationUuidCannotBeArbitraryPath(){fixture{root,_,_->val codec=ZoteroDavCodec(File(root,"transfers"));for(id in listOf("../x","/tmp/x","ABCD2345","","00000000-0000-0000-0000-000000000000/extra"))rejects{codec.reopen(id,target())}}}
    private fun makeZip(root:File,names:List<String>,bytes:ByteArray,extra:ByteArray?=null):File=File(root,UUID.randomUUID().toString()+".zip").also{f->ZipOutputStream(f.outputStream()).use{z->for(name in names){val e=ZipEntry(name);e.time=1_800_000_000_000;if(extra!=null)e.extra=extra;z.putNextEntry(e);z.write(bytes);z.closeEntry()}}}
    @Test fun zipRejectsExtraEntryDirectoryTraversalAndAlias(){fixture{root,file,_->for(names in listOf(listOf("pdf.pdf","extra.txt"),listOf("../pdf.pdf"),listOf("/pdf.pdf"),listOf("a\\pdf.pdf"),listOf("PDF.PDF"),listOf("pdf.pdf/"))){val zip=makeZip(root,names,file.readBytes());rejects{ZoteroDavCodec.verifyZip(zip,"pdf.pdf",facts(file.readBytes()))}}}}
    @Test fun zipRejectsCentralSymlinkRegardlessOfPlatformMarker(){fixture{root,file,_->for(os in listOf(0,3)){val zip=makeZip(root,listOf("pdf.pdf"),file.readBytes());val b=zip.readBytes();val c=(0..b.size-4).first{b[it]==0x50.toByte()&&b[it+1]==0x4b.toByte()&&b[it+2]==1.toByte()&&b[it+3]==2.toByte()};b[c+5]=os.toByte();b[c+40]=0xff.toByte();b[c+41]=0xa1.toByte();zip.writeBytes(b);rejects{ZoteroDavCodec.verifyZip(zip,"pdf.pdf",facts(file.readBytes()))}}}}
    @Test fun zipRejectsUnicodeAlternatePathAndZip64Fields(){fixture{root,file,_->for(id in listOf(0x7075,0x0001)){val extra=byteArrayOf(0x75,0x70,1,0,0);val zip=makeZip(root,listOf("pdf.pdf"),file.readBytes(),extra);if(id==0x0001){val bytes=zip.readBytes();var patched=0;for(i in 0..bytes.size-5)if(bytes[i]==0x75.toByte()&&bytes[i+1]==0x70.toByte()&&bytes[i+2]==1.toByte()&&bytes[i+3]==0.toByte()){bytes[i]=1;bytes[i+1]=0;patched++};assertEquals("Explicit local+central extra fields must exist",2,patched);zip.writeBytes(bytes)};rejects{ZoteroDavCodec.verifyZip(zip,"pdf.pdf",facts(file.readBytes()))}}}}
    @Test fun zipRejectsLocalNameDisagreementAndTruncation(){fixture{root,file,_->val zip=makeZip(root,listOf("pdf.pdf"),file.readBytes());val bytes=zip.readBytes();bytes[30]='x'.code.toByte();zip.writeBytes(bytes);rejects{ZoteroDavCodec.verifyZip(zip,"pdf.pdf",facts(file.readBytes()))};zip.writeBytes(bytes.copyOf(bytes.size-2));rejects{ZoteroDavCodec.verifyZip(zip,"pdf.pdf",facts(file.readBytes()))}}}
    @Test fun zipValidCrcAloneNotEnoughWithoutOriginalShaMd5(){fixture{root,file,_->val zip=makeZip(root,listOf("pdf.pdf"),file.readBytes());val wrong=facts(file.readBytes()).put("sha256","0".repeat(64));rejects{ZoteroDavCodec.verifyZip(zip,"pdf.pdf",wrong)}}}
    @Test fun sparseOversizeFileRejectedBeforeAllocation(){fixture{root,_,_->val f=File(root,"oversize.zip");RandomAccessFile(f,"rw").use{it.setLength(ZoteroDavCodec.MAX_ZIP+1)};rejects{ZoteroDavCodec.verifyZip(f,"pdf.pdf",facts(byteArrayOf(1)))}}}
    @Test fun chunkCancellationNeverProducesReadyJournal(){fixture{root,_,m->var checks=0;rejects{ZoteroDavCodec(File(root,"transfers")).prepare(m,target()){if(++checks==3)throw java.io.InterruptedIOException("synthetic")}};assertTrue(File(root,"transfers").listFiles()!!.all{!File(it,"journal.json").exists()})}}
    @Test fun operationDirectorySwapDuringCopyCannotReceiveAnyNewMaterial(){fixture{root,_,m->val control=File(root,"transfers");val codec=ZoteroDavCodec(control);var checks=0;var replacement:File?=null;rejects{codec.prepare(m,target()){if(++checks==3){val dir=control.listFiles()!!.single{it.isDirectory};val retained=File(root,"retained-copy");assertTrue(dir.renameTo(retained));assertTrue(dir.mkdir());File(dir,"unknown").writeText("keep");replacement=dir}}};assertNotNull(replacement);assertEquals(listOf("unknown"),replacement!!.list()!!.toList());assertEquals("keep",File(replacement,"unknown").readText())}}

}
